USE DATABASE TRUSTED_AI_GOVERNANCE;

SELECT 'TEN_SILVER_TABLES' CHECK_NAME,10 EXPECTED,COUNT(*) ACTUAL,IFF(COUNT(*)=10,'PASS','FAIL') RESULT FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA='SILVER' AND TABLE_NAME IN ('CUSTOMER','ACCOUNT','PAYMENT','PAYMENT_EXCEPTION','SLA_EVENT','OPERATIONS_TEAM','OPERATIONS_USER','REFERENCE_EXCEPTION_REASON','REFERENCE_PAYMENT_THRESHOLD','GOVERNANCE_REFERENCE');

WITH TABLE_TAGS AS (
 SELECT 'CUSTOMER' TABLE_NAME,'CUSTOMER' EXPECTED_DOMAIN,SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.CUSTOMER','TABLE') DATA_LAYER,SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.CUSTOMER','TABLE') SYNTHETIC_DATA,SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.CUSTOMER','TABLE') DATA_DOMAIN,SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.CUSTOMER','TABLE') OWNER_DOMAIN,SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.CUSTOMER','TABLE') PERMITTED_PURPOSE
 UNION ALL SELECT 'ACCOUNT','ACCOUNT',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.ACCOUNT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.ACCOUNT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.ACCOUNT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.ACCOUNT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.ACCOUNT','TABLE')
 UNION ALL SELECT 'PAYMENT','PAYMENT',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT','TABLE')
 UNION ALL SELECT 'PAYMENT_EXCEPTION','PAYMENT_EXCEPTION',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT_EXCEPTION','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT_EXCEPTION','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT_EXCEPTION','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT_EXCEPTION','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT_EXCEPTION','TABLE')
 UNION ALL SELECT 'SLA_EVENT','OPERATIONS',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.SLA_EVENT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.SLA_EVENT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.SLA_EVENT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.SLA_EVENT','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.SLA_EVENT','TABLE')
 UNION ALL SELECT 'OPERATIONS_TEAM','OPERATIONS',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_TEAM','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_TEAM','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_TEAM','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_TEAM','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_TEAM','TABLE')
 UNION ALL SELECT 'OPERATIONS_USER','OPERATIONS',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_USER','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_USER','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_USER','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_USER','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.OPERATIONS_USER','TABLE')
 UNION ALL SELECT 'REFERENCE_EXCEPTION_REASON','REFERENCE',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_EXCEPTION_REASON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_EXCEPTION_REASON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_EXCEPTION_REASON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_EXCEPTION_REASON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_EXCEPTION_REASON','TABLE')
 UNION ALL SELECT 'REFERENCE_PAYMENT_THRESHOLD','REFERENCE',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_PAYMENT_THRESHOLD','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_PAYMENT_THRESHOLD','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_PAYMENT_THRESHOLD','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_PAYMENT_THRESHOLD','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.REFERENCE_PAYMENT_THRESHOLD','TABLE')
 UNION ALL SELECT 'GOVERNANCE_REFERENCE','GOVERNANCE',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.SILVER.GOVERNANCE_REFERENCE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.SILVER.GOVERNANCE_REFERENCE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.GOVERNANCE_REFERENCE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.SILVER.GOVERNANCE_REFERENCE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.SILVER.GOVERNANCE_REFERENCE','TABLE')
)
SELECT TABLE_NAME,'SILVER / TRUE / '||EXPECTED_DOMAIN||' / DATA_GOVERNANCE / TRUSTED_BANKING_OPERATIONS_AI' EXPECTED,CONCAT_WS(' / ',DATA_LAYER,SYNTHETIC_DATA,DATA_DOMAIN,OWNER_DOMAIN,PERMITTED_PURPOSE) ACTUAL,IFF(DATA_LAYER='SILVER' AND SYNTHETIC_DATA='TRUE' AND DATA_DOMAIN=EXPECTED_DOMAIN AND OWNER_DOMAIN='DATA_GOVERNANCE' AND PERMITTED_PURPOSE='TRUSTED_BANKING_OPERATIONS_AI','PASS','FAIL') RESULT FROM TABLE_TAGS ORDER BY TABLE_NAME;

WITH COLUMN_TAGS AS (
 SELECT 'CUSTOMER.CUSTOMER_NAME' OBJECT_COLUMN,'DIRECT_PERSONAL_IDENTIFIER' EXPECTED_CLASSIFICATION,'HIGH' EXPECTED_SENSITIVITY,SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_CLASSIFICATION','TRUSTED_AI_GOVERNANCE.SILVER.CUSTOMER.CUSTOMER_NAME','COLUMN') ACTUAL_CLASSIFICATION,SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SENSITIVITY_LEVEL','TRUSTED_AI_GOVERNANCE.SILVER.CUSTOMER.CUSTOMER_NAME','COLUMN') ACTUAL_SENSITIVITY
 UNION ALL SELECT 'ACCOUNT.ACCOUNT_ID','FINANCIALLY_SENSITIVE','HIGH',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_CLASSIFICATION','TRUSTED_AI_GOVERNANCE.SILVER.ACCOUNT.ACCOUNT_ID','COLUMN'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SENSITIVITY_LEVEL','TRUSTED_AI_GOVERNANCE.SILVER.ACCOUNT.ACCOUNT_ID','COLUMN')
 UNION ALL SELECT 'PAYMENT.PAYMENT_AMOUNT','FINANCIALLY_SENSITIVE','HIGH',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_CLASSIFICATION','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT.PAYMENT_AMOUNT','COLUMN'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SENSITIVITY_LEVEL','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT.PAYMENT_AMOUNT','COLUMN')
 UNION ALL SELECT 'PAYMENT_EXCEPTION.ASSIGNED_ANALYST_ID','OPERATIONAL_SENSITIVE','MODERATE',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_CLASSIFICATION','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT_EXCEPTION.ASSIGNED_ANALYST_ID','COLUMN'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SENSITIVITY_LEVEL','TRUSTED_AI_GOVERNANCE.SILVER.PAYMENT_EXCEPTION.ASSIGNED_ANALYST_ID','COLUMN')
)
SELECT OBJECT_COLUMN,EXPECTED_CLASSIFICATION||' / '||EXPECTED_SENSITIVITY EXPECTED,CONCAT_WS(' / ',ACTUAL_CLASSIFICATION,ACTUAL_SENSITIVITY) ACTUAL,IFF(ACTUAL_CLASSIFICATION=EXPECTED_CLASSIFICATION AND ACTUAL_SENSITIVITY=EXPECTED_SENSITIVITY,'PASS','FAIL') RESULT FROM COLUMN_TAGS ORDER BY OBJECT_COLUMN;
